def get_icon(
    name: str | Any,
    class_name: str = "",
    size: str = "w-5 h-5",
    **attrs: Any,
) -> Any:
    """
    Render a Lucide icon by name.
    """
    if not isinstance(name, str):
        return name

    # A11y default: icons are decorative unless the caller gives them an
    # accessible identity. Hide them from the accessibility tree and keep
    # them out of the (IE/legacy SVG) tab order.
    if not any(
        k in attrs for k in ("aria_label", "aria-label", "role", "aria_hidden")
    ) and "aria-hidden" not in attrs:
        attrs["aria-hidden"] = "true"
        attrs["focusable"] = "false"

    content = ICONS.get(name)
    if content:
        # Check if content looks like a single path d string (old style compat) containing no tags
        if not content.strip().startswith("<") and "M" in content:
            return el(
                "svg",
                el(
                    "path",
                    d=content,
                    stroke_linecap="round",
                    stroke_linejoin="round",
                    stroke_width="2",
                ),
                viewBox="0 0 24 24",
                fill="none",
                stroke="currentColor",
                class_=f"{size} {class_name}",
                **attrs,
            )

        return el(
            "svg",
            raw(content),
            viewBox="0 0 24 24",
            fill="none",
            stroke="currentColor",
            stroke_width="2",
            stroke_linecap="round",
            stroke_linejoin="round",
            class_=f"{size} {class_name}",
            **attrs,
        )

    # Fallback: render raw emoji/Unicode in a span, otherwise empty
    if any(ord(c) > 127 for c in name):
        return el("span", name, class_=class_name)
    return el("span", "", class_=class_name)
